    "supplied_facts": [
      {
        "source": "issue",
        "quote": "`pytest.approx` returns `False` for two finite `Decimal` values even though their exact difference is below the requested `Decimal` tolerance."
      },
      {
        "source": "issue",
        "quote": "Output on pytest 9.1.1:\n\n```text\ndifference: 1E+393\ntolerance: 1E+394\nboth finite: True\nin tolerance: True\nrelative comparison: False\nabsolute comparison: False\n```"
      },
      {
        "source": "issue",
        "quote": "Both comparisons should be `True`."
      },
      {
        "source": "issue",
        "quote": "This appears to happen because [the infinity guard](https://github.com/pytest-dev/pytest/blob/3fd8675d6d798507c06cf9c60753be6d9d7b0e17/src/_pytest/approx.py#L538) calls `math.isinf(abs(self.expected))`, which treats finite `Decimal(\"1e400\")` as binary-float infinity before the exact Decimal tolerance is used."
      },
      {
        "source": "issue",
        "quote": "Environment: CPython 3.12.3, Ubuntu 24.04.4 LTS, Linux 6.8.0-100-generic x86-64."
      },
      {
        "source": "issue",
        "quote": "Reproduced on pytest 9.1.1 and the current `main` commit above."
      }
    ],
